<script setup lang="ts">
import{computed,onMounted,ref,watch}from'vue';import{useRoute}from'vue-router';import DefaultLayout from'@/layouts/DefaultLayout.vue';import BaseButton from'@/components/ui/BaseButton.vue';import LoadingSpinner from'@/components/ui/LoadingSpinner.vue';import{API_BASE_URL,useApi}from'@/composables/useApi';import{useAuthStore}from'@/stores/auth';import type{ApiResponse,Comment,CourseContent,CourseProgress,Lesson}from'@/types';
const route=useRoute(),api=useApi(),auth=useAuthStore(),content=ref<CourseContent|null>(null),progress=ref<CourseProgress|null>(null),selected=ref<Lesson|null>(null),comments=ref<Comment[]>([]),text=ref(''),replyTo=ref<string|null>(null),error=ref(''),courseId=String(route.params.courseId);const lessons=computed(()=>content.value?.sections.flatMap(x=>x.lessons)||[]);const asset=(url:string|null)=>url?.startsWith('http')?url:`${API_BASE_URL.replace('/api/v1','')}${url}`;
async function load(){try{const[c,p]=await Promise.all([api.get<ApiResponse<CourseContent>>(`/courses/${courseId}/content`),api.get<ApiResponse<CourseProgress>>(`/courses/${courseId}/progress`)]);content.value=c.data||null;progress.value=p.data||null;selected.value=selected.value?lessons.value.find(x=>x.id===selected.value?.id)||lessons.value[0]:lessons.value.find(x=>!x.progress?.isCompleted)||lessons.value[0]||null}catch(e){error.value=e instanceof Error?e.message:'Không thể tải nội dung'}}async function complete(){if(!selected.value)return;await api.patch(`/lessons/${selected.value.id}/progress`,{isCompleted:!selected.value.progress?.isCompleted});await load()}async function loadComments(){if(!selected.value)return;try{const r=await api.get<ApiResponse<Comment[]>>(`/lessons/${selected.value.id}/comments`);comments.value=r.data||[]}catch{comments.value=[]}}async function send(){if(!selected.value||!text.value.trim())return;await api.post(`/lessons/${selected.value.id}/comments`,{content:text.value.trim(),parentId:replyTo.value});text.value='';replyTo.value=null;await loadComments()}async function remove(id:string){await api.del(`/comments/${id}`);await loadComments()}watch(()=>selected.value?.id,()=>loadComments());onMounted(load)
</script>
<template><DefaultLayout><div class="min-h-[calc(100vh-64px)] lg:flex"><aside class="border-r bg-white p-5 dark:border-slate-800 dark:bg-slate-900 lg:w-80"><h2 class="text-xl font-black">{{content?.course.title}}</h2><div class="mt-4 h-2 rounded bg-slate-100"><div class="h-full rounded bg-purple-600" :style="{width:`${progress?.progressPercent||0}%`}"></div></div><p class="mt-2 text-xs text-slate-500">{{progress?.completedLessons||0}}/{{progress?.totalLessons||0}} bài hoàn thành</p><div v-for="(section,i) in content?.sections" :key="section.id" class="mt-6"><b>Chương {{i+1}}: {{section.title}}</b><button v-for="lesson in section.lessons" :key="lesson.id" class="mt-2 flex w-full gap-2 rounded-xl px-3 py-2 text-left text-sm" :class="selected?.id===lesson.id?'bg-purple-100 text-purple-700':'text-slate-600'" @click="selected=lesson"><span>{{lesson.progress?.isCompleted?'✓':'○'}}</span>{{lesson.title}}</button></div></aside><main class="flex-1 p-5 lg:p-8"><LoadingSpinner v-if="api.loading.value&&!content"/><p v-else-if="error" class="text-red-600">{{error}}</p><template v-else-if="selected"><p class="text-xs font-bold text-purple-600">{{selected.lessonType}}</p><h1 class="mt-2 mb-6 text-3xl font-black">{{selected.title}}</h1><div class="min-h-64 rounded-2xl border bg-white p-6 dark:border-slate-800 dark:bg-slate-900"><p v-if="selected.lessonType==='TEXT'" class="whitespace-pre-line leading-8">{{selected.content}}</p><video v-else-if="selected.lessonType==='VIDEO'&&selected.videoUrl" :src="asset(selected.videoUrl)||''" controls class="max-h-[520px] w-full"></video><iframe v-else-if="selected.lessonType==='DOCUMENT'&&selected.documentUrl" :src="asset(selected.documentUrl)||''" class="h-[600px] w-full"></iframe><p v-else>Chưa có nội dung.</p></div><div class="my-5 flex flex-wrap gap-3"><BaseButton @click="complete">{{selected.progress?.isCompleted?'Đánh dấu chưa xong':'✓ Đánh dấu hoàn thành'}}</BaseButton><RouterLink v-if="selected.quiz" :to="`/quiz/${selected.quiz.id}`"><BaseButton variant="outline">Làm quiz: {{selected.quiz.title}}</BaseButton></RouterLink></div><section class="mt-8 rounded-2xl border bg-white p-6 dark:border-slate-800 dark:bg-slate-900"><h2 class="mb-4 text-xl font-black">Thảo luận bài học</h2><article v-for="item in comments" :key="item.id" class="border-t py-4 dark:border-slate-800"><b>{{item.user.fullName}}</b><p class="my-2">{{item.isDeleted?'Bình luận đã xóa':item.content}}</p><button v-if="!item.isDeleted" class="text-xs font-bold text-purple-600" @click="replyTo=item.id">Trả lời</button><button v-if="item.user.id===auth.user?.id&&!item.isDeleted" class="ml-3 text-xs font-bold text-red-600" @click="remove(item.id)">Xóa</button><div v-for="reply in item.replies" :key="reply.id" class="mt-3 ml-8 rounded-xl bg-slate-50 p-3 dark:bg-slate-800"><b>{{reply.user.fullName}}</b><p>{{reply.isDeleted?'Bình luận đã xóa':reply.content}}</p></div></article><p v-if="replyTo" class="text-sm text-purple-600">Đang trả lời bình luận <button @click="replyTo=null">Hủy</button></p><textarea v-model="text" rows="3" class="mt-3 w-full rounded-xl border p-3 dark:bg-slate-800" placeholder="Nhập bình luận..."></textarea><BaseButton @click="send">Gửi bình luận</BaseButton></section></template></main></div></DefaultLayout></template>
